-- YG-1297, 1298, 1300, 1315, 1317: entegrasyon envanteri, veri sözleşmesi, sahip/amaç doğrulaması, toplu dosya aktarımı.
ALTER TABLE entegrasyon_tanimi ALTER COLUMN hazirlayan_ref DROP NOT NULL,
  ADD COLUMN teknik_sahip text, ADD COLUMN hizmet_hesabi text, ADD COLUMN uc_nokta text, ADD COLUMN surum text, ADD COLUMN destek_yolu text,
  ADD COLUMN yon text CHECK (yon IN ('Giden', 'Gelen', 'Çift Yönlü')), ADD COLUMN veri_akisi text, ADD COLUMN veri_sozlesmesi jsonb NOT NULL DEFAULT '[]', ADD COLUMN son_dogrulama date, ADD COLUMN dogrulayan_ref text REFERENCES kullanici_hesabi (kimlik);
ALTER TABLE entegrasyon_tanimi DROP CONSTRAINT IF EXISTS entegrasyon_tanimi_durum_check;
ALTER TABLE entegrasyon_tanimi ADD CONSTRAINT entegrasyon_tanimi_durum_check CHECK (durum IN ('Taslak', 'Onayda', 'Üretimde', 'İncelemede', 'Askıda', 'Kapalı'));
CREATE TABLE toplu_aktarim (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), entegrasyon_ref uuid NOT NULL REFERENCES entegrasyon_tanimi (kimlik), donem text NOT NULL, kaynak text NOT NULL, beyan_sayi integer NOT NULL, gercek_sayi integer NOT NULL,
  beyan_ozet text NOT NULL, gercek_ozet text NOT NULL, sema_surumu text NOT NULL, beklenen_sema text, sonuc text NOT NULL CHECK (sonuc IN ('Kabul', 'Kısmi Kabul', 'Karantina')), kabul_sayisi integer NOT NULL, red_sayisi integer NOT NULL,
  red_raporu jsonb NOT NULL DEFAULT '[]', karantina_nedeni text, yukleyen_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), zaman timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT ON toplu_aktarim TO yatonet_uygulama;
INSERT INTO durum_sozlugu (kayit_turu, durum, is_anlami, giris_kosulu, cikis_kosulu, yetkili_rol, izinli_gecisler, zorunlu_aciklama, sure_durur, otomatik_bildirim, musteri_adi) VALUES
 ('entegrasyon_tanimi', 'İncelemede', 'Kayıt yetkili kişi tarafından inceleniyor.', 'Sahibi veya kullanım amacı 12 ay içinde doğrulanmamış bağlantı kendiliğinden incelemeye alınır', 'Sahip ve amaç doğrulanınca Üretimde; gereksizse Kapalı', 'Bilgi Teknolojileri ve Firma Yönetimi Direktörü', ARRAY['Üretimde', 'Kapalı']::text[], false, false, 'Bilgi Teknolojileri ve Firma Yönetimi Direktörüne inceleme görevi', NULL)
ON CONFLICT (kayit_turu, durum) DO NOTHING;
